"""Publish data/path_ranking.json to AutoGenerated/path_ranking.json.

The ranking is written by `python -m metaphysica.testground rank` over a sweep's
finished runs (it cannot be recomputed inside a build). This step copies the
committed file after checking it against the contract; when the file is absent
it skips with a logged line and exits 0.

Copyright (c) 2025-2026 Andrew Keith Watts. All rights reserved.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path
from typing import Optional

from metaphysica.generators._common import autogen_dir

SOURCE = Path(__file__).resolve().parents[1] / "data" / "path_ranking.json"


def publish(source: Path = SOURCE, dest_dir: Optional[Path] = None) -> bool:
    """Copy a valid ranking to ``dest_dir``; False (logged) when absent."""
    from metaphysica.testground.rank import validate_ranking
    if not source.is_file():
        print("path_ranking: %s absent; skipped" % source)
        return False
    doc = json.loads(source.read_text(encoding="utf-8"))
    problems = validate_ranking(doc)
    if problems:
        raise ValueError("path_ranking.json does not validate: "
                         + "; ".join(problems))
    dest = (dest_dir or autogen_dir()) / "path_ranking.json"
    dest.write_text(json.dumps(doc, indent=1, sort_keys=True) + "\n",
                    encoding="utf-8")
    print("path_ranking: published %d paths to %s" % (doc["searched"], dest))
    return True


def main() -> int:
    publish()
    return 0


if __name__ == "__main__":
    sys.exit(main())
